type fullfile_ctx struct{ Context }
func (c fullfile_ctx) do(ctx Context, op any) any {
    switch t := op.(type) {
	case inner_cast: return c.Context
	case dynamic_cast: return t.ctx(c, c.Context)
    case wants_fullfile: return true
    }
    return c.Context.do(ctx, op)
}
func fullfile_if_wanted(ctx Context, f *file) Value {
	// NOTE: see also general_opts.fullname, exec_ctx.do, etc.
	if f == nil { return nil }
    if truly(ctx, wants_fullfile{}) { return fullfile{f} }
    return f
}

