func _raw(pos Pos, s string) Value { if s == "" { return valbase{pos} } else { return &raw{valbase{pos},s} } }
func _rw(pos Pos, s string) Value {
	if s == "" { return valbase{pos} }
	if len(s) < 64 {
		var ok bool
		var sym Symbol
		h := hashStr(s)
		vocab.RLock()
		for _, sym = range vocab.strsyms[h] {
			if ok = symEqualsStringLocked(sym, s); ok { break }
		}
		vocab.RUnlock()
		if ok { return &word{valbase{pos}, sym} }
	}
	return &raw{valbase{pos}, s}
}
func _rw1(pos Pos, s string) Value {
	if s == "" { return valbase{pos} }

	// Fast path: strings under 64 bytes are interned as *word.
	if len(s) < 64 {
		var ok bool
		var sym Symbol
		h := hashStr(s)
		vocab.RLock()
		for _, sym = range vocab.strsyms[h] {
			if ok = symEqualsStringLocked(sym, s); ok { break }
		}
		vocab.RUnlock()

		// If found in vocab, return the word immediately.
		if ok {
			return &word{valbase{pos}, sym}
		}

		// THE DOD FIX: Force dynamic interning!
		// If patsubst generates a new path segment (e.g., "__cxxabi_config.h"),
		// we MUST explicitly intern it here to guarantee it becomes a *word,
		// ensuring perfect AST parity with statically parsed paths!
		return &word{valbase{pos}, intern(s)}
	}

	// Extremely long strings (>= 64 bytes) are kept as raw to avoid polluting the intern map.
	return &raw{valbase{pos}, s}
}

func makeDate(pos Pos, s time_pkg.Time) *date  { return &date{datetime{valbase{pos},s}} }
func makeTime(pos Pos, t time_pkg.Time) *time  { return &time{datetime{valbase{pos},t}} }
func makeUrl(pos Pos, s *neturl.URL) *url {
	if s.RawQuery != "" { panic("TODO: url query: "+s.RawQuery) }

    var host, port string
    var v = strings.Split(s.Host, ":")
    if len(v) == 1 { host = v[0] }
    if len(v) == 2 { host, port = v[0], v[1] }

    var password Value
    if pw, ok := s.User.Password(); ok { password = _raw(pos, pw) }
    return &url{ // FIXME: calculate component positions
        Scheme:   _word(pos, intern(s.Scheme)),
        Username: _raw(pos, s.User.Username()),
        Password: password,
        Host:     _word(pos, intern(host)),
        Port:     _word(pos, intern(port)),
        Path:     _word(pos, intern(s.Path)),
        // Query:    _word(pos, intern(s.RawQuery)),
        Fragment: _word(pos, intern(s.Fragment)),
    }
}

