func walkSmartBaseDirs(ctx Context, cwd Symbol, vis func(Symbol) bool) Symbol {
	for s := cwd; s != symEmpty && s != symDot && s != symPathSep; {
		// Use pure Symbol ID for VFS lookup!
		f := _stat(ctx, symDotSmart, stat_dir{s})
		if f.exists() && f.isDir() && !vis(s) {
			return s
		}

		up := __symDir(s)
		if up == s {
			break
		}
		s = up
	}
	// Return symEmpty instead of cwd so the caller knows it failed!
	return symEmpty
}

var tmpPathOnce sync.Once // Guarantees the walk only happens exactly once!

func joinTmpPath(ctx Context, base, rel Symbol) Symbol {
	// 1. Thread-safe Lazy Initialization
	tmpPathOnce.Do(func() {
		s := walkSmartBaseDirs(ctx, base, func(d Symbol) bool {
			return false // return the first found
		})

		if s == symEmpty {
			s = intern(os.TempDir())
		}

		// Map the dynamically found path into our hardcoded Constant slot!
		bindLateConstantAlias(symBaseTmpPath, s)
	})

	if s := __symDir(rel); s != symEmpty && s != symDot {
		if __symHasSuffix(base, s) {
			// In case like '/foo/bar/a/b/c/x' + 'a/b/c/x' -> 'x'
			rel = __symBase(rel)
		} else {
			t := __symPathRel(symBaseTmpPath, base)
			tSeq := __symSeq(t)

			// strings.HasPrefix(t, ".smart" + pathSep)
			if len(tSeq) >= 2 && tSeq[0] == symDotSmart && tSeq[1] == symSlash {
				v1 := __symSplit(t, symSlash)
				v2 := __symSplit(s, symSlash)

				for i := len(v1) - 1; i >= 0; i-- {
					if v1[i] == v2[0] {
						if i > 0 {
							base = __symPathJoin(v1[i-1:]...)
						} else {
							base = __symPathJoin(v1...)
						}
						break
					}
				}
			}
		}
	}

	if s := __symPathRel(symBaseTmpPath, __symPathJoin(base, rel)); s != symEmpty {
		rel = s
	}

	// --- Prefix Trimming ---
	relSeq := __symSeq(rel)
	trimStart := 0

	// Trim ".smart/"
	if len(relSeq) >= 2 && relSeq[0] == symDotSmart && relSeq[1] == symSlash {
		trimStart = 2
		// Trim "modules/"
		if len(relSeq) >= 4 && relSeq[2] == symModules && relSeq[3] == symSlash {
			trimStart = 4
		}
	}
	if trimStart > 0 {
		relSeq = relSeq[trimStart:]
		rel = internSeq(relSeq) // Update rel natively!
	}

	// --- Replace ".." with "_" ---
	replaced := false
	for _, sym := range relSeq {
		if sym == symDotDot {
			replaced = true
			break
		}
	}

	if replaced {
		clean := make([]Symbol, len(relSeq))
		for i, sym := range relSeq {
			if sym == symDotDot {
				clean[i] = symUnderscore // Directly map the integer!
			} else {
				clean[i] = sym
			}
		}
		relSeq = clean
		rel = internSeq(clean)
	}

	// --- Final Path Generation ---
	if len(relSeq) >= 2 && relSeq[0] == symTmp && relSeq[1] == symSlash {
		return __symPathJoin(symBaseTmpPath, symDotSmart, rel)
	}

	return __symPathJoin(symBaseTmpPath, symDotSmart, symTmp, rel)
}

func loadSearchPaths(ctx Context, s Symbol) (paths []Symbol) {
	// 1. Zero-Allocation Path Generation
	searchFileSym := __symPathJoin(s, symDotSearch)

	// THE AIRLOCK: Unpack string exactly once for bulk I/O
	data, err := os.ReadFile(searchFileSym.String())
	if err != nil {
		return nil
	}

	// Iterate over bytes directly to avoid string allocations for comments/blank lines
	lines := bytes.Split(data, []byte{'\n'})

	// Pre-allocate paths slice to minimize dynamic array resizing
	paths = make([]Symbol, 0, len(lines))

	for _, bLine := range lines {
		// Fast in-place byte trimming
		bLine = bytes.TrimSpace(bLine)

		if len(bLine) == 0 || bLine[0] == '#' {
			continue
		}

		// Re-enter the Walled Garden immediately!
		lineSym := intern(string(bLine))

		// 2. Walled Garden Path Normalization
		if !__symIsAbs(lineSym) {
			lineSym = __symPathJoin(s, lineSym)
		}

		// 3. VFS Cache Hit instead of os.Stat!
		// Because this runs at startup, it effectively pre-warms the cache
		// for all search paths the compiler will need later!
		if f := _stat(ctx, lineSym); f != nil && f.isDir() {
			paths = append(paths, lineSym)
		}
	}
	return paths
}

type main_ctx struct{ Context }
func (m main_ctx) do(c Context, op any) any {
    switch t := op.(type) {
	case inner_cast: return m.Context
	case dynamic_cast: return t.ctx(m, m.Context)
    }
	return m.Context.do(c, op)
}

func Main() {
	if checkpoints { panic("Smart in testmode!") }

	// Boot the universe first. It will now yield a perfectly scrubbed paths array!
	ctx := new_universe()

	// =================================================================
	// 1. MODULE SEARCH PATH RESOLUTION (using statcache & deduplication)
	// =================================================================
	var modules = filepath.FromSlash(`.smart/modules`)

	// 1a. Search underneath Standard Roots & Workspace
	for _, root := range []string{`/Volumes`, `/media`, `/`, os.Getenv("HOME")} {
		if root == "" { continue }
		for _, base := range []string{root, filepath.Join(root, "workspace")} {
			sym := intern(filepath.Join(base, modules))
			if f := _stat(ctx, sym); f != nil && f.isDir() {
				// Prevent double-adding if new_universe already found it
				if !ctx.paths.has(sym) { ctx.paths = append(ctx.paths, sym) }
			}
		}
	}

	// 1b. Search within GOPATH splits
	if gopath := os.Getenv("GOPATH"); gopath != "" {
		for _, root := range filepath.SplitList(gopath) {
			if root == "" { continue }
			for _, base := range []string{root, filepath.Join(root, "src")} {
				sym := intern(filepath.Join(base, modules))
				if f := _stat(ctx, sym); f != nil && f.isDir() {
					if !ctx.paths.has(sym) { ctx.paths = append(ctx.paths, sym) }
				}
			}
		}
	}

	// =================================================================
	// 2. UNIVERSE LOADING & EXECUTION
	// =================================================================
	ctx.load(main_ctx{ctx})

	if ctx.flush(ctx) > 0 {
		prompt(ctx, "loading work got %d errors\n", ctx.erros)
	} else if ctx.help {
		do_helpscreen(ctx)
	} else if ctx.printFlags {
		print_flag_trace(ctx)
	} else if ctx.printConfig {
		print_configuration(ctx)
	} else if numUpdatedPlugins > 0 { // see buildPlugin
		prompt(ctx, "plugins updated, please relaunch.\n")
	} else if result := ctx.run(main_ctx{ctx}); ctx.flush(ctx) > 0 {
		prompt(ctx, "run work got %d errors\n", ctx.erros)
	} else if result != nil {
		for i, v := range result {
			if s := ""; v == nil {
				s = "<nil>"
			} else if s = strings.TrimSpace(__string(ctx, v)); s == "" {
				continue
			} else if i == 0 {
				fmt.Fprintf(stderr, "%s", s)
			} else {
				fmt.Fprintf(stderr, ", %s", s)
			}
		}
		fmt.Fprintf(stderr, "\n")
	}
}

type searched_path struct{ sym Symbol ; isDir bool }
type search_path struct{ sym Symbol }
type searchlist []Symbol
func (sl *searchlist) String() string {
	var sb strings.Builder
	for i, s := range *sl {
		if i > 0 { sb.WriteByte(' ') }
		sb.WriteString(s.String())
	}
	return sb.String()
}
func (sl *searchlist) has(s Symbol) bool {
	for _, t := range *sl { if s == t { return true } }
	return false
}
