func (ctx *universe) String() string { return "universe" }

func (ctx *universe) _position() (p Position) {
    if ctx.globe != nil && ctx.globe.main != nil && ctx.fset != nil {
		p = ctx.fset.Position(ctx.globe.main.pos)
    } else {
		p.Filename, p.Line, p.Column = symBaseWorkDir, 0, 0
	}
    return
}

func (ctx *universe) trimFileSpec(c Context, spec Symbol) Symbol {
	if spec == symEmpty {
		return symEmpty
	}

	// 1. Emulate strings.ReplaceAll(spec, "../", "")
	seq := __symSeq(spec)
	hasDotDot := false
	for _, s := range seq {
		if s == symDotDot {
			hasDotDot = true
			break
		}
	}

	if hasDotDot {
		clean := make([]Symbol, 0, len(seq))
		for i := 0; i < len(seq); i++ {
			if seq[i] == symDotDot {
				// Skip the symDotDot AND the trailing slash (just like ReplaceAll)
				if i+1 < len(seq) && seq[i+1] == symSlash {
					i++
				}
				continue
			}
			clean = append(clean, seq[i])
		}
		spec = internSeq(clean)
	}

	// 2. Zero-allocation helper to match and trim "dirSym + symSlash"
	trimDirSlash := func(target Symbol, dirSym Symbol) Symbol {
		if dirSym == symEmpty { return target }

		dirSeq := __symSeq(dirSym)
		if len(dirSeq) == 0 { return target }

		tSeq := __symSeq(target)

		// If dir already inherently ends in a slash, use standard prefix match
		if dirSeq[len(dirSeq)-1] == symSlash {
			if __symHasPrefix(target, dirSym) {
				return __symTrimPrefix(target, dirSym)
			}
			return target
		}

		// O(1) Lookahead Match: Does target start with dir AND have a trailing slash?
		if len(tSeq) > len(dirSeq) && tSeq[len(dirSeq)] == symSlash {
			match := true
			for i := 0; i < len(dirSeq); i++ {
				if tSeq[i] != dirSeq[i] {
					match = false
					break
				}
			}
			if match {
				// Trim both the dir sequence and the trailing slash!
				return internSeq(tSeq[len(dirSeq)+1:])
			}
		}
		return target
	}

	// 3. Check and trim paths (now operating purely on Symbols!)
	for _, s := range ctx.paths {
		newSpec := trimDirSlash(spec, s)
		if newSpec != spec {
			spec = newSpec
			break
		}
	}

	// 4. Check and trim workdir (now operating purely on Symbols!)
	return trimDirSlash(spec, symBaseWorkDir)
}

func (u *universe) do(ctx Context, op any) (res any) {
	switch t := op.(type) {
	case inner_cast:
		return &u.diagnostic
	case dynamic_cast:
		return t.ctx(ctx, &u.diagnostic)
	case get_pos:
		return NoPos
	case get_fatpos:
		if t.p != NoPos && u.fset != nil { return u.fset.Position(t.p) }
	case get_scope:
		if u.scope != nil { return u.scope }
	case get_project:
		if u.globe != nil { return u.globe.main }
	case exec_noop:
		if u.noExec { return u.noExec }
	case is_test_mode:
		if u.testMode { return true }

	case get_closure_scopes:
		var res []*scope
		if u.scope != nil       { res = add_closure_scopes(res, u.scope)       }
		if u.globe.scope != nil { res = add_closure_scopes(res, u.globe.scope) }

		if t.n > 0 && len(res) >= t.n { return res[:t.n] }

		if cc := u.Context; cc != nil {
			nextOp := t
			if t.n > 0 { nextOp.n = t.n - len(res) }

			if x, y := do(cc, nextOp).([]*scope); y && x != nil {
				res = add_closure_scopes(res, x...)
			}
		}

		if t.n > 0 && len(res) > t.n { return res[:t.n] }
		return res

	case declared_project:
		if t.project == nil {
			erro(ctx, "declared nil project", trace_ctx{100}, callstack{stop: "smart.Main"})
			return
		}

		// RULE 1: ALL projects must be cached to prevent load drops
		if p, ok := u.globe.loaded[t.absPath]; !ok {
			u.globe.loaded[t.absPath] = t.project
			u.globe.loadedProjs = append(u.globe.loadedProjs, t.project)
		} else if p != t.project {
			ds := []*diag{_f("re-declared project, probably cycled `use` %v → %v", p.name, t.name)}
			ds = append(ds, _fLoadedProjs(u, 0, "loaded-project: %[3]s → %[1]s")...)
			if false {
				erro(pc(ctx, p.pos), ds, trace_ctx{100}, callstack{num: 10})
			} else {
				note(pc(ctx, p.pos), ds, trace_ctx{100}, callstack{num: 10})
			}
		}

		// RULE 2: ONLY the entry-point gets to be 'main'
		if t.absPath == u.workdir {
			var properName = t.name
			for s := t.scope; s != nil && s != u.globe.scope && s.project != nil; s = s.outer {
				if s.project.name == symAt { properName = symEmpty; break }
			}
			switch properName {
			case symEmpty, symAt, symTilde, symConfigure, symDotConfigure:
				// Special configuration scripts are exempted from being 'main'
			default:
				u.globe.main = t.project

				for _, p := range u.globe.pairs {
					switch k := p.key.(type) {
					case *word, *compound, flag:
						t.scope.def(ctx, defDecl, __symbol(ctx, k), p.val)
					default:
						erro(ctx, "%v: unknown target: %v : %v", t.name, p, ts(p, ctx),
							trace_ctx{100}, callstack{num: 10})
					}
				}
			}
		}

	case cachestat:
		// HIGH-SPEED FAST PATH: 100% lock-free atomic map lookup requires
		// zero mutex locking and zero allocations for 99% of processing steps.
		if val, ok := u.statcache.Load(t.cleanFullname); ok {
			return val.(*filebase)
		}

		// SLOW PATH: Instantiate and seed the lock-free data base structure
		base := &filebase{
			stub: filestub{dir: t.dir, sub: t.sub, name: t.name},
		}
		// FIXED: Corrected assignment statement to use atomic Store barrier API
		base.stub.other.Store(&base.stub)

		// Atomic LoadOrStore ensures that if a parallel thread beat us to initialization,
		// the redundant allocation is safely dropped and the true graph node winner is returned.
		if actual, loaded := u.statcache.LoadOrStore(t.cleanFullname, base); loaded {
			return actual.(*filebase)
		}
		return base

	case search_path:
		if t.sym != symEmpty {
			for _, baseSym := range u.paths {
				joinedSym := __symPathJoin(baseSym, t.sym)

				if !__symIsAbs(baseSym) {
					joinedSym = __symPathJoin(symBaseWorkDir, joinedSym)
				}

				// CRITICAL FIX: Pass stat_nonexist{true} to explicitly avoid
				// nil-pointer reference panics on missing path candidates!
				if f := _stat(ctx, joinedSym, stat_nonexist{true}); f != nil && f.exists() {
					return searched_path{sym: joinedSym, isDir: f.isDir()}
				}
			}
		}
		return searched_path{sym: symEmpty, isDir: false}
	}
	return u.diagnostic.do(ctx, op)
}

