// create closure context for the traversal
type modifier_closure struct { modifier_
    target Value `@,target`
}
func (ctx *modifier_closure) x(exe *execution, args ...Value) (result any) {
	// Closure the caller program, the context will be restored when execution is finished.
	var cc = exe.Context

	if exe.closure != nil {
		warn(ctx, "already closure: %v", exe.closure, trace_ctx{5}, callstack{num:5})
	}
	if caller := exe.caller(); caller != nil {
		if caller.closure == nil {
			exe.closure = caller.scope
		} else {
			exe.closure = caller.closure
		}
	}

	if false && cast[*term](ctx) != exe.Context {
		erro(ctx, "wrong closure_with")
	}

	// =====================================================================
	// STRUCTURE SCOPE RESOLUTION FIX
	// =====================================================================
	// Replaced legacy direct field reading with a defensive check against
	// the rule's definition project domain.
	var proj = _project(ctx)
	if proj == nil && exe.prog != nil { proj = exe.prog.project }
	if checkpoints {
		if _project(ctx) != proj {
			debug(ctx, "%v != %v", _project(ctx), proj)
		}
	}

	// CRITICAL FIX: Upgraded internal helper to accept sym Symbol
	var set = func(sym Symbol, val Value) (t Value) {
		var noop bool
		if v, y := val.(*boolean); y {
			if !v.bool { noop = true }
		} else if isTrivial(val) {
			erro(ctx, "trivial target: %T %v", val, val)
		} else if true {
			t = expand(ctx, val) //, plain
		} else {
			t = val
		}

		if l, y := t.(*list); y && len(l.elems) == 1 { t = l.elems[0] }

		// FAST INTEGER LOOKUP!
		if !noop && isTrivial(t) { t = auto_get(ctx, sym) }

		if t != nil {
			// FAST INTEGER ASSIGNMENT!
			auto_set(ctx, defVoid, sym, t) // aka (set @=&@)
		} else if !noop {
			// FIXED: Replaced %s with %v to natively print the Symbol
			erro(ctx, "%v: %v is nil", proj, sym)
		}
		return
	}

	var target Value
	if ctx.target != nil {
		if target = expand(ctx, ctx.target); target == ctx.target {
			// CRITICAL FIX: Use the native symAt constant instead of symAt
			if t := auto_get(cc, symAt); t != nil {
				target = t
			}
		}
	}

	if ctx.verbose {
		var t = target
		debug(ctx, "%v: @: %v ⇒ %v %v", proj, ctx.target, typeof(t), t)
	}

	if target != nil {
		t := set(symAt, target)

		// 1. Walled Garden Domain Extraction (Mirrors the `dirty` function!)
		projs := exe.traverseProjs()
		f := as_file(ctx, t, projs...)
		sSym, _ := fullname_sym(ctx, t)

		n := 0
		// if f != nil { n = int(f._traved) }
		if n > 1 {
			if ctx.verbose {
				// AIRLOCK: Only extract the string for the terminal output!
				ts := trimPrompt(sSym.String())
				prompt(ctx, "%s …… traversed (%d, %v)\n", ts, n)
				if false { debug(ctx, "%v, %v, (%d)", f, sSym, n) }
			}
			return
		}

		// FIXME: if isInnerauto_get(ctx, t.Value) {
		//      erro(ctx, "loop: %v", t)
		//      return
		// }
	}

	if proj == nil {
		erro(ctx, "%T: nil project in the context", ctx)
	} else if scope := proj.scope; scope == nil {
		erro(ctx, "empty closure context")
	} else if def := scope.finddef(symSlash); def == nil {
		erro(ctx, "&/ is undefined")
	} else {
		// 2. ZERO-ALLOCATION DIRECTORY CHECK
		dirSym := __symbol(ctx, def.value)

		if dirSym == symEmpty {
			erro(ctx, "&/ is empty")
		} else if !__symIsAbs(dirSym) {
			erro(ctx, "&/ is relative")
		} else /* if err := enter(ctx, dirSym.String()); err == nil */ {
			// 3. Final OS Airlock!
			exe.changedWD = dirSym
		}
	}
	return
}

type modifier_cd struct{ modifier_
    path bool `path`
    printEnter bool `print-enter`
    printLeave bool `print-leave`
}
func (ctx *modifier_cd) x(exe *execution, args ...Value) (result any) {
	if (ctx.printEnter || ctx.printLeave) && len(args) == 0 { return }

	// Safety Barrier: Ensure the execution handle exists
	if exe == nil {
		erro(ctx, "nil execution handle inside cd modifier", trace_ctx{5}, callstack{num: 10})
		return
	}

	if len(args) == 1 {
		// 1. Enter the Walled Garden natively via Symbol domain
		dirSym := __symbol(ctx, args[0])
		if dirSym == symEmpty {
			return
		}

		// 2. Progressive Stateful Path Calculations
		// If the input path is relative, evaluate it against the current live
		// runtime working directory boundary rather than jumping back to the project root.
		if !__symIsAbs(dirSym) {
			if exe.workdir != symEmpty {
				dirSym = __symPathJoin(exe.workdir, dirSym)
			} else {
				proj := _project(ctx)
				if proj != nil {
					dirSym = __symPathJoin(proj.absPath, dirSym)
				}
			}
		}

		// 3. Optional Virtual Filesystem Lazy Path Initialization
		if ctx.path && dirSym != symDot && dirSym != symDotDot && dirSym != symPathSep {
			// Airlock: Unpack the string path exactly once for OS system calls
			dirStr := dirSym.String()
			if err := os.MkdirAll(dirStr, 0755); err != nil {
				debug(ctx, "make path '%s' failed: %v", dirStr, err)
			}
		}

		// 4. Update the Stateful Engine Parameters Directly
		// This sets the new base-path for downstream shell command builders
		exe.workdir = dirSym
		exe.changedWD = dirSym
	} else {
		erro(ctx, "wrong number of cd args: %v", args)
	}
	return
}

type modifier_mkdir struct { modifier_
    mode os.FileMode `mode`
}
func (ctx *modifier_mkdir) x(args ...Value) (result any) {
	if ctx.mode == 0 {
		ctx.mode = os.FileMode(0755)
	} else {
		ctx.mode |= os.FileMode(0111)
	}

	if len(args) == 0 {
		if v := auto_get(ctx, symAt); !isTrivial(v) {
			args = append(args, v)
		}
	}

	for _, a := range xmerge(final{ctx}, args...) {
		// 1. Walled Garden Resolution
		// This flawlessly replaces your manual `a.(*file)` type switch!
		sym, _ := fullname_sym(ctx, a)
		if sym == symEmpty {
			continue
		}

		// 2. THE AIRLOCK: Extract the string exactly once for the OS boundary
		str := sym.String()

		// 3. Standard string validation
		// (Since we already needed the string for MkdirAll, doing this here is 0-allocation!)
		if strings.Contains(str, " /") || strings.Contains(str, " ./") || strings.Contains(str, " ../") {
			erro(ctx, "multiple paths (%v): '%v'", typeof(a), str)
			continue // Prevent the OS call if validation fails
		} else if strings.Contains(str, " ") {
			debug(ctx, "path containing spaces (%v): '%v'", typeof(a), str)
		}

		// 4. Physical OS Execution
		if e := os.MkdirAll(str, ctx.mode); e != nil {
			erro(ctx, "path: %v(%v) ⇒ %s: %v", typeof(a), a, str, e)
		}
	}
	return
}

