func (ctx *__noop) do(c Context, op any) any {
	switch t := op.(type) {
	case inner_cast: return &ctx.builtinbase
	case dynamic_cast: return t.ctx(ctx, &ctx.builtinbase)
	}
	return ctx.builtinbase.do(c, op)
}
func (ctx *__noop) x() (_ any) { return }

type __typeof struct { builtinbase }
func (ctx *__typeof) do(c Context, op any) any {
	switch t := op.(type) {
	case inner_cast: return &ctx.builtinbase
	case dynamic_cast: return t.ctx(ctx, &ctx.builtinbase)
	}
	return ctx.builtinbase.do(c, op)
}
func (ctx *__typeof) x() (res any) {
    var vals []Value
    for _, a := range ctx.a {
        // Arguments are passed in a list:
        //   $(fun abc)             args: (abc)
        //   $(fun a,b,c)           args: (a),(b),(c)
        //   $(fun a b c,1 2 3)     args: (a b c),(1 2 3)
        vals = append(vals, _word(a.Pos(), intern(typeof(a))))
    }
    return vals
}

