func (ctx *__filter) _x0(pats []Value, values ...Value) (result []Value) {
	defer func(t0 time_pkg.Time) {
		if d := time_pkg.Since(t0); d > 1*time_pkg.Second {
			debug(ctx,
				_f("slow: %v\n", d),
				_f("slow: %d result, %v\n", len(result), result),
				_f("slow: %d pats, %v\n", len(pats), pats))
		}
	}(time_pkg.Now())

	if len(values) == 0 {
		return
	}

	// 1. OPTIMIZATION: Pre-allocate capacity to eliminate slice growth allocations.
	// Filter-out (ctx.neg) typically keeps most items, while filter keeps fewer.
	capacity := len(values) / 2
	if ctx.neg {
		capacity = len(values)
	}
	result = make([]Value, 0, capacity)

	// 2. OPTIMIZATION: Memoization cache for repetitive AST nodes.
	// This prevents executing O(N * M) match() calls for duplicate values.
	type matchResult struct {
		matched bool
		val     Value // Stores the stem or the original value
	}
	cache := make(map[string]matchResult, capacity)

	for _, v := range values {
		// Use the string representation as the identity key. Expanded AST nodes
		// (like *word or *strlit) that represent the same text will hit the cache.
		var key string
		if v != nil {
			key = v.String()
		}

		// Fast-path: If we've already matched this exact string against the patterns, reuse it!
		if cached, exists := cache[key]; exists {
			if cached.matched {
				if !ctx.neg && cached.val != nil {
					result = append(result, cached.val)
				}
			} else {
				if ctx.neg && v != nil {
					result = append(result, v)
				}
			}
			continue
		}

		var matched bool
		var matchedVal Value

		// Slow-path: Check the value against all patterns
		for _, pat := range pats {
			if full, _, _, stems := match(ctx, pat, v); full {
				matched = true
				if ctx.stem {
					matchedVal = ease(ctx, stems)
				} else {
					matchedVal = v
				}
				break // Stop checking patterns once we have a match
			}
		}

		// Save the computed result into the cache for future identical values
		cache[key] = matchResult{
			matched: matched,
			val:     matchedVal,
		}

		// Apply filter vs filter-out logic
		if matched {
			if !ctx.neg {
				if matchedVal != nil {
					result = append(result, matchedVal)
				}
			}
		} else {
			if ctx.neg {
				if v != nil {
					result = append(result, v)
				}
			}
		}
	}
	return
}
func (ctx *__filter) _x(pats []Value, values ...Value) (result []Value) {
	if benchmark {
		defer func(t0 time_pkg.Time) {
			if d := time_pkg.Since(t0); d > 25*time_pkg.Millisecond {
				debug(ctx,
					_f("slow: %d values, %v, %d result", len(values), d, len(result)),
					_f("slow: %d pats: %v", len(pats), pats),
					callstack{num: 10})
			}
		}(time_pkg.Now())
	}

	if len(values) == 0 {
		return
	}

	capacity := len(values) / 2
	if ctx.neg {
		capacity = len(values)
	}
	result = make([]Value, 0, capacity)

	// =====================================================================
	// Symbol Domain Optimization: Pre-compile fast-path matchers
	// =====================================================================
	type fastPattern struct {
		isExact  bool
		exact    Symbol
		isPerc   bool
		prefix   string
		suffix   string
		fallback Value
	}

	fastPats := make([]fastPattern, 0, len(pats))
	for _, pat := range pats {
		fp := fastPattern{fallback: pat}
		p := unloc(pat)

		if pp, ok := p.(*percpat); ok {
			pfxSym := __symbol(ctx, pp.Prefix)

			sufVal := pp.Suffix
			if inner, isPP := unloc(sufVal).(*percpat); isPP && isEmpty(inner.Prefix) {
				sufVal = inner.Suffix // Handle %%
			}
			sufSym := __symbol(ctx, sufVal)

			fp.isPerc = true
			fp.prefix = pfxSym.String()
			fp.suffix = sufSym.String()
		} else if !patterned(ctx, p) {
			fp.isExact = true
			fp.exact = __symbol(ctx, p)
		}
		// *regexpat is DELIBERATELY excluded here. It relies on the pure AST
		// fallback `match(ctx, fp.fallback, v)` to avoid standard library allocations.

		fastPats = append(fastPats, fp)
	}

	// =====================================================================
	// Symbol Domain Memoization Cache: Allocation-Free Lookups
	// =====================================================================
	type matchResult struct {
		matched bool
		val     Value
	}
	cache := make(map[Symbol]matchResult, capacity)

	for _, v := range values {
		if v == nil {
			continue
		}

		vSym := __symbol(ctx, v)
		// GUARD: Only utilize the cache and string-conversion fast paths if the
		// value is a pure scalar/word. Complex AST nodes bypass the cache to avoid collisions.
		isCacheable := vSym != symEmpty && !patterned(ctx, v)

		if isCacheable {
			if cached, exists := cache[vSym]; exists {
				if cached.matched {
					if !ctx.neg && cached.val != nil {
						result = append(result, cached.val)
					}
				} else {
					if ctx.neg {
						result = append(result, v)
					}
				}
				continue
			}
		}

		var matched bool
		var matchedVal Value
		var vStr string

		if isCacheable {
			vStr = vSym.String() // Pull string view exactly once
		}

		for _, fp := range fastPats {
			if fp.isExact && isCacheable {
				// Fast pointer comparison for direct scalar literals
				if vSym == fp.exact {
					matched = true
					if ctx.stem {
						matchedVal = _word(v.Pos(), symEmpty)
					} else {
						matchedVal = v
					}
					break
				}
			} else if fp.isPerc && isCacheable {
				if len(vStr) >= len(fp.prefix)+len(fp.suffix) &&
					strings.HasPrefix(vStr, fp.prefix) &&
					strings.HasSuffix(vStr, fp.suffix) {
					matched = true
					if ctx.stem {
						stemStr := vStr[len(fp.prefix) : len(vStr)-len(fp.suffix)]
						matchedVal = _word(v.Pos(), intern(stemStr))
					} else {
						matchedVal = v
					}
					break
				}
			} else {
				// Heavy AST Matcher Fallback (Natively handles *regexpat, *globpat, etc.)
				if full, _, _, stems := match(ctx, fp.fallback, v); full {
					matched = true
					if ctx.stem {
						matchedVal = ease(ctx, stems)
					} else {
						matchedVal = v
					}
					break
				}
			}
		}

		if isCacheable {
			cache[vSym] = matchResult{
				matched: matched,
				val:     matchedVal,
			}
		}

		if matched {
			if !ctx.neg && matchedVal != nil {
				result = append(result, matchedVal)
			}
		} else {
			if ctx.neg {
				result = append(result, v)
			}
		}
	}
	return
}

func (ctx *__filter) x() (res any) {
	if len(ctx.a) > 1 {
		var i int
		var pats = merge(expand(ctx, ctx.a[0]))

		if len(pats) > 0 {
			i = 1
		} else if pats = merge(ctx.a[1]); len(pats) == 0 {
			erro(ctx, "no patterns: %v", ctx.a)
			return
		} else {
			i = 2
		}

		if i <= len(ctx.a) {
			res = ctx._x(pats, merge(expands(ctx, ctx.a[i:]...)...)...)
		} else {
			erro(ctx, "out of index: %d > %d, %v", i, len(ctx.a), ctx.a)
		}
	}
	return
}

