func (ctx *__writefile) x() (res any) {
    // $(write-file    filename,content)
    // $(write-file -p filename,content)
outer:
    for i := 0; i < len(ctx.a); i += 1 {
        var (
            a = ctx.a[i]
            name, data string
            perm = os.FileMode(0600)
        )
        switch t := a.(type) {
        case *pair: // write-file name=text name=text
            name = __string(ctx, t.key)
            data = __string(ctx, t.val)
        case *group: // write-file (name text) (name text 0660)
            if n := t.len(); n < 4 && n > 0 {
                name = __string(ctx, t.at(0))
                if n > 1 { data = __string(ctx, t.at(1)) }
                if n > 2 { perm = filePerm(ctx, t.at(2),0600) }
            } else {
                erro(ctx, "Wrong size of group `%v'", t)
            }
        case *list: // write-file name text, name text 0660, ...
            if n := t.len(); n < 4 && n > 0 {
                name = __string(ctx, t.at(0))
                if n > 1 { data = __string(ctx, t.at(1)) }
                if n > 2 { perm = filePerm(ctx, t.at(2),0600) }
            } else {
                erro(ctx, "Wrong size of list `%v'", t)
            }
        default: // write-file name text 0660  name text 0660 ...
            name = __string(ctx, ctx.a[i])
            if i+1 < len(ctx.a) {
                data = __string(ctx, ctx.a[i+1])
                i += 1
            }
            if i+1 < len(ctx.a) {
                perm = filePerm(ctx, ctx.a[i+1],0600)
                i += 1
            }
        }
        if name == "" {
            continue outer
        } else if dir := filepath.Dir(name); ctx.path && dir != "." && dir != pathSep {
            if err := os.MkdirAll(dir, os.FileMode(0755)); err != nil {
                erro(ctx, "%v", err)
            }
        }
        if err := ioutil.WriteFile(name, []byte(data), perm); err != nil {
            erro(ctx, "%v", err)
        }
    }
    return
}

func touch(ctx Context, file Value, optMode uint32, optPath bool, ts ...time_pkg.Time) (err error) {
	// 1. Enter the Walled Garden natively
	var a, filenameSym = file_fullname(ctx, file)

	if filenameSym == symEmpty {
		erro(ctx, "touch: empty file name: %v (%v, %v, %v)", file, typeof(file), a)
	}

	// 2. Pure Integer Path Math!
	if optPath {
		d := __symDir(filenameSym)
		// Compare against Walled Garden constants instead of strings
		if d != symDot && d != symSlash {
			// THE OS AIRLOCK (Directory)
			if err = os.MkdirAll(d.String(), os.FileMode(optMode|0733)); err != nil {
				erro(ctx, "touch: %v", err)
			}
		}
	}

	var (
		mode = os.FileMode(optMode)
		ta, tm time_pkg.Time
		m os.FileMode
	)
	if len(ts) > 0 { ta = ts[0] } else { ta = time_pkg.Now() }
	if len(ts) > 1 { tm = ts[1] } else { tm = time_pkg.Now() }

	// =========================================================
	// THE OS AIRLOCK: Extract the string EXACTLY ONCE for file ops
	// =========================================================
	filenameStr := filenameSym.String()

	// COLD PATH: We don't cache os.FileMode anymore, so pull it straight from disk
	if fi, e := os.Stat(filenameStr); e == nil && fi != nil {
		m = fi.Mode()
	} else {
		var f *os.File
		if m = mode; m == 0 { m = os.FileMode(0600); mode = m }
		if f, err = os.OpenFile(filenameStr, os.O_RDWR|os.O_CREATE|os.O_APPEND, m&os.ModePerm); err != nil {
			erro(ctx, "touch: %v", err)
		} else if err = f.Close(); err != nil {
			erro(ctx, "touch: %v", err)
		}
	}

	if err == nil {
		if err = os.Chtimes(filenameStr, ta, tm); err != nil {
			erro(ctx, "touch: %v", err)
		}

		// RE-ENTER THE WALLED GARDEN:
		// Now that the OS disk is updated, we instantly sync the physical
		// timestamp back into our `int64` VFS cache!
		if f, _ := to_file(file); f != nil {
			f.stat(ctx, true)
		} else if f := _stat(ctx, filenameSym); f != nil { // Pure Symbol cache lookup
			// Done!
		}
	}

	if err == nil && mode != 0 && m != 0 && mode != m {
		if err = os.Chmod(filenameStr, mode); err != nil {
			erro(ctx, "touch: %v", err)
		}
	}
	return
}

